from simulator import Strategy, Context

class MarketplaceDemoStrategy(Strategy):
    def on_init(self, ctx: Context) -> None:
        self.total_signals = 0

    def on_bar(self, ctx: Context) -> None:
        # 1. Calling marketplace indicator without importing it in strategy file!
        st = ctx.indicators.supertrend(period=12, multiplier=1.8)
        if len(st) < 15:
            return
        st_val = float(st.iloc[-1])

        # 2. Record telemetry along the way (for UI charts)
        ctx.record(
            supertrend_value=st_val,
            bar_range=float(ctx.candle.high - ctx.candle.low)
        )

        # 3. Simple entry/exit logic
        if not ctx.has_position and ctx.price > st_val:
            ctx.buy(usd_amount=1500.0, stop_loss=ctx.price * 0.97, take_profit=ctx.price * 1.06)
            self.total_signals += 1
        elif ctx.has_position and ctx.price < st_val:
            ctx.close_all(reason='SuperTrend Break')

    def on_stop(self, ctx: Context) -> dict:
        return {'signals_count': self.total_signals}

